module asyn_fifo #(
    parameter DEPTH = 16,
    parameter WIDTH = 8,
    parameter ADDR_WIDTH = $clog2(DEPTH)
) (
    input 					wclk,
    input 					rclk,
    input 					wrstn,
    input					rrstn,
    input 					winc,
    input 			 		rinc,
    input 		[WIDTH-1:0]	wdata,
    output wire				wfull,
    output wire				rempty,
    output wire [WIDTH-1:0]	rdata
);


	wire wen, ren;
	reg [WIDTH-1:0] wdata_reg, rdata_reg;

	assign wen = winc && !wfull;
	assign ren = rinc && !rempty;
	assign wdata_reg = wdata;
	assign rdata = rdata_reg;

	dual_port_RAM #(.DEPTH(DEPTH), .WIDTH(WIDTH)) ram(
		.wclk(wclk),
		.wenc(wen),
		.waddr(waddr),
		.wdata(wdata_reg),
		.rclk(rclk),
		.renc(ren),
		.raddr(raddr),
		.rdata(rdata_reg)
	);

	reg [$clog2(DEPTH):0] wptr, rptr;
	reg [$clog2(DEPTH):0] wptr_bin, rptr_bin;
	reg [$clog2(DEPTH):0] wptr_buff, rptr_buff;
	reg [$clog2(DEPTH):0] wptr_syn, rptr_syn;

	always @(posedge wclk or negedge wrstn) begin
		if(!wrstn) begin
			wptr <= 0;
			wptr_buff <= 0;
		end
		else begin
			if(wen) begin
				wptr <= wptr + 1;
				wptr_buff <= wptr;
			end
		end
	end

	always @(posedge rclk or negedge rrstn) begin
		if(!rrstn) begin
			rptr <= 0;
			rptr_buff <= 0;
		end
		else begin
			if(ren) begin
				rptr <= rptr + 1;
				rptr_buff <= rptr;
			end
		end
	end

	function automatic [$clog2(DEPTH)+1:0] bin_to_gray(input [$clog2(DEPTH)+1:0] bin);
		integer i;
		reg [$clog2(DEPTH)+1:0] temp;
		begin
			temp = bin;
			for(i=$clog2(DEPTH); i>=0; i=i-1) begin
				bin_to_gray[i] = temp[i];
				temp[i-1] = temp[i] ^ temp[i-1];
			end
		end
	endfunction

	function automatic [$clog2(DEPTH)+1:0] gray_to_bin(input [$clog2(DEPTH)+1:0] gray);
		integer i;
		reg [$clog2(DEPTH)+1:0] temp;
		begin
			temp[$clog2(DEPTH)] = gray[$clog2(DEPTH)];
			for(i=$clog2(DEPTH)-1; i>=0; i=i-1) begin
				temp[i] = temp[i+1] ^ gray[i];
			end
			gray_to_bin = temp;
		end
	endfunction

	always @(posedge rclk or negedge rrstn) begin
		if(!rrstn) begin
			wptr_syn <= 0;
		end
		else begin
			wptr_syn <= wptr_buff;
		end
	end

	always @(posedge wclk or negedge wrstn) begin
		if(!wrstn) begin
			rptr_syn <= 0;
		end
		else begin
			rptr_syn <= rptr_buff;
		end
	end

	assign wfull = (wptr == {~rptr_syn[4], rptr_syn[3:0]});
	assign rempty = (rptr == wptr_syn);

	assign waddr = wptr_bin[$clog2(DEPTH)-1:0];
	assign raddr = rptr_bin[$clog2(DEPTH)-1:0];

	always @(*) begin
		wptr_bin = gray_to_bin(wptr);
		rptr_bin = gray_to_bin(rptr);
	end

	assign wen = winc && !wfull;
	assign ren = rinc && !rempty;
endmodule

module dual_port_RAM #(parameter DEPTH = 16,  parameter WIDTH = 8)
(
	 input wclk	,
	 input wenc	,
	 input [$clog2(DEPTH)-1:0] waddr  ,
	 input [WIDTH-1:0] wdata ,
	 input rclk	,
	 input renc	,
	 input [$clog2(DEPTH)-1:0] raddr ,
	 output reg [WIDTH-1:0] rdata 		
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
	if(wenc)
		RAM_MEM[waddr] <= wdata;
end 

always @(posedge rclk) begin
	if(renc)
		rdata <= RAM_MEM[raddr];
end 

endmodule
